package org.praskanth.entity;

import jakarta.persistence.*;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * One checkout that used a coupon. {@code checkoutRef} is generated by order-service for each "Place order" click
 * (a cart with several sellers produces several orders but ONE redemption), and its uniqueness makes redeem() and
 * release() safe to retry.
 */
@Entity
@Table(name = "coupon_redemptions",
        uniqueConstraints = @UniqueConstraint(name = "uk_redemption_checkout", columnNames = "checkout_ref"),
        indexes = @Index(name = "idx_redemption_coupon_user", columnList = "coupon_id, user_id, status"))
@Getter
@Setter
@NoArgsConstructor
public class CouponRedemption {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "coupon_id", nullable = false)
    private Long couponId;

    @Column(name = "user_id", nullable = false)
    private Long userId;

    @Column(name = "checkout_ref", nullable = false, length = 64)
    private String checkoutRef;

    @Column(name = "discount_amount", nullable = false, precision = 12, scale = 2)
    private BigDecimal discountAmount;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private RedemptionStatus status;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @Column(name = "released_at")
    private Instant releasedAt;

    @PrePersist
    void onCreate() {
        createdAt = Instant.now();
    }
}
